<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('quotations.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'quotation_versions');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='new_version'){$qid=fint('quotation_id');$q=db_one($pdo,'SELECT current_version_no,subtotal,discount_amount,tax_amount,total_amount,internal_cost FROM quotations WHERE id=?',[$qid]);if($q){$v=(int)$q['current_version_no']+1;$pdo->prepare('INSERT INTO quotation_versions(quotation_id,version_no,status,subtotal,discount_amount,tax_amount,total_amount,internal_cost,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$qid,$v,'draft',$q['subtotal'],$q['discount_amount'],$q['tax_amount'],$q['total_amount'],$q['internal_cost'],fpost('notes')?:null,$staff['id']]);$pdo->prepare('UPDATE quotations SET current_version_no=? WHERE id=?')->execute([$v,$qid]);flash('success','New quotation version created.');}}elseif($a==='approval'){$pdo->prepare('INSERT INTO approval_requests(request_type,entity_type,entity_id,requested_by,status,reason) VALUES(?,?,?,?,?,?)')->execute(['quotation_discount','quotation',fint('quotation_id'),$staff['id'],'pending',fpost('reason')?:'Quotation approval requested']);$pdo->prepare('UPDATE quotations SET status="pending_approval" WHERE id=?')->execute([fint('quotation_id')]);flash('success','Approval requested.');}staff_redirect('staff/pages/quotation-centre.php');}
$quotes=db_rows($pdo,'SELECT q.*,c.name customer_name,p.project_code,(SELECT COUNT(*) FROM quotation_versions v WHERE v.quotation_id=q.id) version_count FROM quotations q LEFT JOIN customers c ON c.id=q.customer_id LEFT JOIN projects p ON p.id=q.project_id ORDER BY q.created_at DESC');$approvals=db_rows($pdo,'SELECT a.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) requester FROM approval_requests a LEFT JOIN staff s ON s.id=a.requested_by WHERE a.entity_type="quotation" ORDER BY a.created_at DESC LIMIT 20');$pageTitle='Quotation Centre';require __DIR__.'/../../includes/staff/header.php';module_head('Sales','Quotation Centre','Manage revisions, internal costing and approval requests without overwriting history.');?>
<section class="staff-panel table-panel"><table><thead><tr><th>Quotation</th><th>Customer / project</th><th>Status</th><th>Version</th><th>Selling</th><th>Internal cost</th><th>Actions</th></tr></thead><tbody><?php foreach($quotes as $r):?><tr><td><b><?=h($r['quotation_no'])?></b></td><td><?=h($r['customer_name']?:'—')?><small><?=h($r['project_code']?:'')?></small></td><td><span class="pill"><?=h($r['status'])?></span></td><td>v<?=$r['current_version_no']?> (<?=$r['version_count']?> saved)</td><td>RM <?=number_format($r['total_amount'],2)?></td><td>RM <?=number_format($r['internal_cost'],2)?></td><td><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="action" value="new_version"><input type="hidden" name="quotation_id" value="<?=$r['id']?>"><input name="notes" placeholder="Revision note"><button class="btn">New version</button></form><form method="post" class="toolbar" style="margin-top:6px"><?=csrf_field()?><input type="hidden" name="action" value="approval"><input type="hidden" name="quotation_id" value="<?=$r['id']?>"><input name="reason" placeholder="Approval reason"><button class="btn">Request approval</button></form></td></tr><?php endforeach?></tbody></table></section><section class="staff-panel"><h2>Recent approval requests</h2><?php foreach($approvals as $a):?><div class="board-card"><b>Approval #<?=h($a['id'])?></b> · <?=h($a['status'])?><small><?=h($a['requester']?:'Unknown')?> · <?=h($a['reason']?:'')?></small></div><?php endforeach?></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>